# -*- coding: utf-8 -*-
# Quotes registry: id -> dict(lang, text, book (shamela id or 'or:<file>'), page, cite, anchor(optional))
Q = {}
def ar(id, text, book, page, cite, note=''):
    Q[id] = dict(lang='ar', text=text, book=book, page=page, cite=cite, note=note)
def en(id, text, file, page, cite, anchor, note=''):
    Q[id] = dict(lang='en', text=text, book='or:'+file, page=page, cite=cite, anchor=anchor, note=note)

# ---------- عربي: أهمية الفقه ----------
ar('A01', 'ووكل بحفظها من الصحابة والتابعين من تقوم به الحجة، وترتفع بقوله الشبهة، وهم الفقهاء الذين ألزمهم حراسة شريعته', 13048, 69, 'الخطيب البغدادي، الفقيه والمتفقه، ج١ ص٦٩')
ar('A02', 'فحرس بيضة الإسلام بالمجاهدين وحفظ شريعة الإيمان بالمتعلمين', 13048, 69, 'الخطيب البغدادي، الفقيه والمتفقه، ج١ ص٦٩')
ar('A03', 'فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم إذا رجعوا إليهم لعلهم يحذرون', 13048, 69, 'التوبة: ١٢٢ (كما أوردها الخطيب، الفقيه والمتفقه ج١ ص٦٩)')
ar('A04', 'من يرد الله به خيرا يفقهه في الدين', 735, 39, 'البخاري، صحيح البخاري، كتاب العلم، حديث ٧١ (ط. البغا ج١ ص٣٩)')
