ar('A10', 'الاختلاف من وجهين أحدهما محرم ولا أقول ذلك في الآخر', 8180, 560, 'الشافعي، الرسالة، باب الاختلاف، ص٥٦٠ (ت. شاكر)')
ar('A11', 'كل ما أقام الله به الحجة في كتابه أو على لسان نبيه منصوصا بينا لم يحل الاختلاف فيه لمن علمه', 8180, 560, 'الشافعي، الرسالة، ص٥٦٠')
ar('A12', 'وما كان من ذلك يحتمل التأويل ويدرك قياسا فذهب المتأول أو القايس إلى معنى يحتمله الخبر أو القياس', 8180, 560, 'الشافعي، الرسالة، ص٥٦٠')
ar('A13', 'فأما ما كلفوا فيه الاجتهاد', 8180, 561, 'الشافعي، الرسالة، ص٥٦١')
ar('A14', 'فقالت عائشة الأقراء الأطهار', 8180, 562, 'الشافعي، الرسالة، ص٥٦٢')
ar('A15', 'وقال نفر من أصحاب النبي الأقراء الحيض', 8180, 562, 'الشافعي، الرسالة، ص٥٦٢')
# ---------- عربي: أسباب الاختلاف ----------
ar('A20', 'وأما أسباب الاختلاف بالجنس فستة', 21739, 12, 'ابن رشد، بداية المجتهد ونهاية المقتصد، ج١ ص١٢')
ar('A21', 'لفظ القرء الذي ينطلق على الأطهار وعلى الحيض', 21739, 12, 'ابن رشد، بداية المجتهد، ج١ ص١٢')
ar('A22', 'والفقه أن ينظر بأيهما هو أقوى شبها فيلحق به', 21739, 15, 'ابن رشد، بداية المجتهد، ج١ ص١٥')
ar('A23', 'أن أثبت فيه لنفسي على جهة التذكرة من مسائل الأحكام المتفق عليها والمختلف فيها بأدلتها', 21739, 9, 'ابن رشد، بداية المجتهد، ج١ ص٩')
ar('A24', 'ليس أحد من الأئمة -المقبولين عند الأمة قبولا عاما- يتعمد مخالفة رسول الله صلى الله عليه وسلم في شيء من سنته؛ دقيق ولا جليل', 4118, 8, 'ابن تيمية، رفع الملام عن الأئمة الأعلام، ص٨')
ar('A25', 'فإنهم متفقون اتفاقا يقينيا على وجوب اتباع الرسول صلى الله عليه وسلم', 4118, 9, 'ابن تيمية، رفع الملام، ص٩')
ar('A26', 'وجميع الأعذار ثلاثة أصناف', 4118, 9, 'ابن تيمية، رفع الملام، ص٩')
ar('A27', 'أن لا يكون الحديث قد بلغه', 4118, 9, 'ابن تيمية، رفع الملام، ص٩ (السبب الأول)')
ar('A28', 'فيكون عند هؤلاء من العلم ما ليس عند هؤلاء، وعند هؤلاء ما ليس عند هؤلاء', 4118, 10, 'ابن تيمية، رفع الملام، ص١٠')
ar('A29', 'وأما إحاطة واحد بجميع حديث رسول الله صلى الله عليه وسلم، فهذا لا يمكن ادعاؤه قط', 4118, 10, 'ابن تيمية، رفع الملام، ص١٠')
ar('A30', 'فهذه الأسباب العشرة ظاهرة', 4118, 35, 'ابن تيمية، رفع الملام، ص٣٥')
ar('A31', 'فإن مدارك العلم واسعة', 4118, 35, 'ابن تيمية، رفع الملام، ص٣٥')
ar('A32', 'إذا اجتهد الحاكم فأصاب فله أجران, وإذا اجتهد فأخطأ فله أجر', 4118, 38, 'ابن تيمية، رفع الملام، ص٣٨ (حديث في الصحيحين كما أورده)')
ar('A33', 'فتبين أن المجتهد مع خطئه له أجر؛ وذلك لأجل اجتهاده', 4118, 38, 'ابن تيمية، رفع الملام، ص٣٨')
ar('A34', 'لا يصلين أحد العصر إلا في بني قريظة', 4118, 39, 'ابن تيمية، رفع الملام، ص٣٩ (حديث في الصحيحين كما أورده)')
ar('A35', 'فلم يعب واحدة من الطائفتين', 4118, 39, 'ابن تيمية، رفع الملام، ص٣٩')
ar('A36', 'ومع هذا فالذين صلوا في الطريق كانوا أصوب فعلا', 4118, 39, 'ابن تيمية، رفع الملام، ص٣٩')
ar('A37', 'لم يكن الفقه في زمانه الشريف مدونا', 422, 15, 'الدهلوي، الإنصاف في بيان أسباب الاختلاف، ص١٥')
ar('A38', 'ما رأيت قوما كانوا خيرا من أصحاب رسول الله صلى الله عليه وسلم ما سألوه إلا عن ثلاث عشرة مسألة', 422, 16, 'الدهلوي، الإنصاف، ص١٦ (عن ابن عباس)')

ar('A16', 'والمطلقات يتربصن بأنفسهن ثلاثة قروء', 8180, 562, 'البقرة: ٢٢٨ (كما أوردها الشافعي، الرسالة ص٥٦٢)')
ar('A17', 'ولما قدم سرغ وبلغه أن الطاعون بالشام، استشار المهاجرين الأولين الذين معه، ثم الأنصار، ثم مسلمة الفتح', 4118, 12, 'ابن تيمية، رفع الملام، ص١٢')
ar('A18', 'فهذه مواضع لم يكن يعلمها عمر -رضي الله عنه- حتى بلغه إياها من ليس مثله', 4118, 13, 'ابن تيمية، رفع الملام، ص١٣')
ar('A55', 'ولم يكن عيبا في حق عمر -رضي الله عنه- حيث لم يبلغه الحديث', 4118, 14, 'ابن تيمية، رفع الملام، ص١٤')
ar('A19', 'ثم سئلت عن سبب اختلاف الصحابة ومن بعدهم في الأحكام الفقهية خاصة', 422, 14, 'الدهلوي، الإنصاف في بيان أسباب الاختلاف، ص١٤')
ar('A51', 'وليس لأحد أن يعارض الحديث الصحيح عن النبي صلى الله عليه وسلم بقول أحد من الناس', 4118, 36, 'ابن تيمية، رفع الملام، ص٣٦')
ar('A52', 'أقول قال رسول الله صلى الله عليه وسلم، وتقولون قال أبو بكر وعمر', 4118, 37, 'ابن تيمية، رفع الملام، ص٣٧ (قول ابن عباس)')
ar('A53', 'والواجب عند اختلاف العلماء طلب الدليل من الكتاب والسنة والإجماع', 22367, 903, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٣ (قول مالك والشافعي ومن معهما، كما حكاه ابن عبد البر)')
ar('A54', 'وأما المفتون فغير جائز عند أحد ممن ذكرنا قوله لأحد أن يفتي ولا يقضي إلا حتى يتبين له وجه ما يفتي به من الكتاب أو السنة أو الإجماع', 22367, 904, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٤')
# ---------- عربي: عن علم لا عن هوى ----------
ar('A40', 'لقد أوسع الله على الناس باختلاف أصحاب محمد صلى الله عليه وسلم، أي ذلك أخذت به لم يكن في نفسك منه شيء', 22367, 901, 'ابن عبد البر، جامع بيان العلم وفضله، ج٢ ص٩٠١ (عن القاسم بن محمد)')
ar('A41', 'لا تفعل فما يسرني أن لي باختلافهم حمر النعم', 22367, 901, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠١ (عمر بن عبد العزيز للقاسم بن محمد)')
ar('A42', 'ما أحب أن أصحاب رسول الله صلى الله عليه وسلم لم يختلفوا؛ لأنه لو كان قولا واحدا كان الناس في ضيق', 22367, 902, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٢ (عمر بن عبد العزيز)')
ar('A43', 'هذا فيما كان طريقه الاجتهاد', 22367, 902, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٢ (تعليق ابن عبد البر)')
ar('A44', 'خطأ وصواب فانظر في ذلك', 22367, 905, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٥ (مالك)')
ar('A45', 'لا تجوز الفتوى إلا لمن علم ما اختلف الناس فيه', 22367, 818, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٨١٨ (مالك)')
ar('A46', 'ما برح المستفتون يستفتون فيحل هذا ويحرم هذا فلا يرى المحرم أن المحلل هلك لتحليله ولا يرى المحلل أن المحرم هلك لتحريمه', 22367, 903, 'ابن عبد البر، جامع بيان العلم، ج٢ ص٩٠٣ (يحيى بن سعيد)')
ar('A47', 'إن الناس قد سبقت إليهم أقاويل وسمعوا أحاديث ورووا روايات وأخذ كل قوم بما سبق إليهم', 6733, 41, 'ابن عبد البر، الانتقاء في فضائل الثلاثة الأئمة الفقهاء، ص٤١ (مالك للمنصور)')
ar('A48', 'فدع الناس وما هم عليه وما اختار أهل كل بلد لأنفسهم', 6733, 41, 'ابن عبد البر، الانتقاء، ص٤١ (مالك للمنصور)')
ar('A49', 'قال يونس الصدفي: ما رأيت أعقل من الشافعي، ناظرته يوما في مسألة، ثم افترقنا، ولقيني، فأخذ بيدي، ثم قال: يا أبا موسى، ألا يستقيم أن نكون إخوانا وإن لم نتفق في مسألة', 10906, 16, 'الذهبي، سير أعلام النبلاء، ج١٠ ص١٦ (ط. الرسالة)')
ar('A50', 'إذا اختلف المجتهدون من العلماء في مسألة على قولين أو أكثر، فقد ذكر عن أبي حنيفة أنه قال: كل مجتهد مصيب والحق ما غلب على ظن المجتهد', 13048, 114, 'الخطيب البغدادي، الفقيه والمتفقه، ج٢ ص١١٤')
# ---------- English ----------
en('E01', "Islamic law is the epitome of Islamic thought, the most typical manifestation of the Islamic way of life, the core and kernel of Islam itself.", 'schachtU', 1, 'Joseph Schacht, An Introduction to Islamic Law (Oxford: Clarendon Press, 1964), p. 1', 'epitome of')
en('E02', "The very term fiqh, 'knowledge', shows that early Islam regarded knowledge of the sacred Law as the knowledge par excellence.", 'schachtU', 1, 'Schacht, An Introduction to Islamic Law, p. 1', 'knowledge of the sacred Law')
en('E03', "it is impossible to understand Islam without understanding Islamic law.", 'schachtU', 1, 'Schacht, An Introduction to Islamic Law, p. 1', 'impossible to understand Islam')
en('E04', "Islamic law provides us with a remarkable example of the possibilities of legal thought and of human thought in general, and with a key to understanding the essence of one of the great world religions.", 'schachtU', 'Preface', 'Schacht, An Introduction to Islamic Law, Preface', 'remarkable example of the possibilit')
en('E05', "In their relationship to one another, the orthodox schools of law have, notwithstanding acts of fanaticism, particularly on the part of the populace and of the rulers in the high Middle Ages, generally practised mutual toleration. This attitude goes back to the time of the ancient schools of law which had accepted geographical differences of doctrine as natural.", 'schachtU', 67, 'Schacht, An Introduction to Islamic Law, p. 67', 'In their relationship to one another')
en('E06', "The maxim that disagreement (ikhtilaf) in the community of Muslims was a sign of divine indulgence had already been formulated in the second century of the hijra, though it was put into the mouth of the Prophet only much later.", 'schachtU', 67, 'Schacht, An Introduction to Islamic Law, p. 67', 'sign of divine')
en('E07', "their alternative interpretations are all equally valid, their methods of reasoning equally legitimate; in short, they are equally orthodox.", 'schachtU', 67, 'Schacht, An Introduction to Islamic Law, p. 67', 'equally orthodox')
en('E08', "I should not like it if they had not disagreed", 'schachtO', 96, "Joseph Schacht, The Origins of Muhammadan Jurisprudence (Oxford: Clarendon Press, 1950; repr. 1967), p. 96 (re: 'Umar b. 'Abd al-'Aziz)", 'not like it if they had not')
en('E09', "On one side, they accept the geographical differences of doctrine as natural; on the other, they uphold their consensus", 'schachtO', 96, 'Schacht, The Origins of Muhammadan Jurisprudence, p. 96', 'geographical differences of doctrine as natural')
en('E10', "This maxim became, much later, a saying of the Prophet, but neither Abu Hanifa, nor Shafi'i, nor the classical collections of traditions knew it as such.", 'schachtO', 96, 'Schacht, The Origins of Muhammadan Jurisprudence, p. 96, n. 3', 'This maxim became, much later')
en('E11', "it is characteristic of the practical bent of the Islamic community and of its thought that its earliest activity and most highly developed expression is in law rather than in theology.", 'gibb', 88, 'H. A. R. Gibb, Mohammedanism: An Historical Survey (New York: Oxford University Press, Galaxy Book, 1962), p. 88', 'practical bent of the Islamic community')
en('E12', "a structure of law that is, from the point of view of logical perfection, one of the most brilliant essays of human reasoning.", 'gibb', 90, 'Gibb, Mohammedanism, p. 90', 'most brilliant essays')
en('E13', "the moral authority of the Law was but the more enhanced and held the social fabric of Islam compact and secure through all the fluctuations of political fortune.", 'gibb', 11, 'Gibb, Mohammedanism, p. 11', 'moral authority of the Law')
en('E14', "by its unity and comprehensiveness it formed the main unifying force in Islamic culture.", 'gibb', 106, 'Gibb, Mohammedanism, p. 106', 'unifying force in Islamic culture')
en('E15', "He was said to have called it a proof of God's special mercy, that within reasonable limits difference of opinion was allowed in his community. Of that privilege Mohammedans have always amply availed themselves.", 'hurgronje', '68-69', 'C. Snouck Hurgronje, Mohammedanism: Lectures on Its Origin, Its Religious and Political Growth, and Its Present State (New York: G. P. Putnam\'s Sons, 1916), pp. 68-69', 'proof of God')
en('E16', "does not the infallible Agreement of the Community teach us that a certain diversity of opinion is a merciful gift of God?", 'hurgronje', 74, 'Hurgronje, Mohammedanism, p. 74', 'merciful gift of God')
en('E17', "This indivi- dual ijtihad explains the plurality of opinion in Islamic law, known as khilaf or ikhtilaf.", 'hallaqU', 130, 'Wael B. Hallaq, The Origins and Evolution of Islamic Law (Cambridge: Cambridge University Press, 2005), p. 130', 'plurality of opinion in Islamic law')
en('E18', "All jurists are assumed to be “doing the right thing” in exerting their juristic effort (ijtihad) in reaching a rule or an opinion.", 'hallaqU', 130, 'Hallaq, The Origins and Evolution of Islamic Law, p. 130', 'doing the right thing')
en('E19', "One jurist’s inference is therefore as good as that of another, hence the cardinal maxim: “All qualified jurists are correct.”", 'hallaqU', 130, 'Hallaq, The Origins and Evolution of Islamic Law, p. 130', 'cardinal maxim')
en('E20', "Each case may elicit two, three, sometimes up to eight or more opinions, all of which remain “opinions” that are equally valid", 'hallaqU', 130, 'Hallaq, The Origins and Evolution of Islamic Law, p. 130', 'sometimes up to eight')
en('E21', "Without this assumption it is difficult to understand how it was possible that during the second century various teachings about ritual and legal problems sprang up in the several madhahib, and even in the same madhhab, with which harmonizing theologists could do no more than consider them as equally justified, and even declare their very diversity to be a blessing to the Islamic community.", 'goldM2', 78, 'Ignaz Goldziher, Muslim Studies, vol. II, ed. S. M. Stern, trans. C. R. Barber and S. M. Stern (London: George Allen & Unwin, 1971), p. 78', 'Without this assumption it is difficult')

en('E22', "In theory and logic, however, a given problem can have only one correct solution, irrespective of whether or not the community of jurists knows which one it is.", 'hallaqU', 130, 'Hallaq, The Origins and Evolution of Islamic Law, p. 130', 'can have only one correct solution')
